import type { DatabaseSync } from 'node:sqlite';

// Seed audit clauses that were added after the initial Excel import.
// Uses INSERT OR IGNORE — safe to run on every startup.
// Each row: [clause_no, clause_title, standard, section, section_no, simple_meaning, audit_questions, documents_required, applicable_process, original_requirement]
type ClauseRow = [string,string,string,string,string,string,string,string,string,string];

const NEW_CLAUSES: ClauseRow[] = [
// ── ISO 9001:2015 additional clauses ──────────────────────────────────────
['4.4.1','QMS Processes — General','ISO','Context of the Organization','4','Organization must identify all processes needed for the QMS, their sequence, interaction, inputs, outputs, owners, risks, and resources.','1. Show me your process map or turtle diagrams. Are all key processes documented?\n2. For each process, who is the process owner — show the accountability matrix.\n3. How do you determine process inputs, outputs, and interaction points?\n4. How are process performance criteria (KPIs) established and monitored?\n5. What changes have been made to processes in the last 12 months — what triggered them?','Process Map, Turtle Diagrams, Process KPI Register, Process Owner Matrix','All processes','The organization shall establish, implement, maintain and continually improve a QMS, including the processes needed and their interactions.'],
['4.4.2','QMS Processes — Documentation','ISO','Context of the Organization','4','Maintain documented information to support process operation and retain documented information to have confidence processes are being carried out as planned.','1. How do you decide what needs to be documented vs. what can be communicated verbally?\n2. Show me how process documentation links to work instructions at shop floor level.\n3. How are process records retained and retrieved — show me a sample.\n4. When a process changes, how is the documentation updated and communicated?\n5. What records do you keep to prove processes ran as planned — show last month examples.','Documented Process Procedures, Work Instructions, Training Records, Process Records','Document Control','The organization shall maintain documented information to support the operation of its processes.'],
['5.1.1','Leadership and Commitment — General','ISO','Leadership','5','Top management must demonstrate personal commitment to the QMS — not just delegate it.','1. How does top management personally demonstrate commitment to quality — beyond signing the quality policy?\n2. Show me the last management review — who attended and what decisions were made?\n3. How has top management integrated quality objectives into the business plan?\n4. When was the last time the plant head walked the shop floor for quality? What was observed?\n5. How does top management ensure sufficient resources are provided for quality?','Management Review Minutes, Quality Business Plan, Leadership Walk Records','Top Management','Top management shall demonstrate leadership and commitment with respect to the QMS.'],
['6.1.2','Actions to Address Risks and Opportunities','ISO','Planning','6','After identifying risks and opportunities, the organization must plan WHAT to do, HOW to implement actions, and HOW to evaluate their effectiveness.','1. Show me your Risk and Opportunity Register — who maintains it and how often is it updated?\n2. For the top 3 risks, what specific actions are planned — show the action plan.\n3. How are risk mitigation actions integrated into process planning (APQP, PFMEA)?\n4. How do you measure whether risk actions were effective — show an example.\n5. Who reviews and approves the Risk Register — is there management involvement?','Risk and Opportunity Register, Action Plans, Effectiveness Review Records','Quality Management','The organization shall plan actions to address risks and opportunities and evaluate the effectiveness of these actions.'],
['6.2.2','Quality Objectives — Planning How to Achieve','ISO','Planning','6','After setting quality objectives, the organization must plan: what will be done, what resources are needed, who is responsible, when it will be completed, and how results will be evaluated.','1. Show me the Quality Objectives with their action plans — not just targets, but HOW you will achieve them.\n2. For each objective, who is accountable — is it documented?\n3. What resources (people, equipment, budget) are allocated to achieve quality objectives?\n4. What is the timeline for each objective — are milestones tracked?\n5. How do you measure progress mid-year — show me the last quarterly review.','Quality Objectives Action Plan, Resource Allocation Records, Review Minutes','Quality Management','The organization shall determine what will be done, what resources will be required, who will be responsible, when it will be completed, and how results will be evaluated.'],
['6.3','Planning of Changes','ISO','Planning','6','When changes to the QMS are needed, they must be carried out in a planned manner considering purpose, integrity of the QMS, resource availability, and responsibility allocation.','1. Show me the last 3 significant QMS changes — how were they planned and approved?\n2. Who authorizes changes to the QMS — is there a formal change control process?\n3. How do you assess the risk of a proposed QMS change before implementing it?\n4. When a change is made, how do you communicate it to affected personnel?\n5. How do you verify that the change achieved the intended result and did not cause unintended consequences?','Change Management Log, Change Request Forms, Impact Assessment Records','Quality Management','When the organization determines the need for changes to the QMS, the changes shall be carried out in a planned manner.'],
['7.1.1','Resources — General','ISO','Support','7','Top management must determine and provide resources needed for QMS: people, infrastructure, environment, monitoring/measurement, and organizational knowledge.','1. How does top management determine what resources are needed for quality activities?\n2. Are quality resources reviewed during budget planning — show evidence.\n3. When quality department requested additional resources, how was it handled — show an example.\n4. Are there constraints on internal resources that require use of external providers — how is this controlled?\n5. How do you ensure resources keep pace with production growth or new customer requirements?','Resource Planning Records, Budget Approvals, Organization Chart','Top Management','The organization shall determine and provide the resources needed for the establishment, implementation, maintenance and continual improvement of the QMS.'],
['7.1.2','People','ISO','Support','7','Organization must determine and provide the persons necessary for the effective implementation of its QMS and for the operation and control of its processes.','1. Is the quality team size adequate for the volume and complexity of complaints handled?\n2. Show me how staffing levels are determined — is there a workload analysis?\n3. What happens when a key quality person is absent — is there a backup plan?\n4. Are temporary or contract workers included in quality competency planning?\n5. How has the quality headcount changed in the last 2 years — was it planned or reactive?','Organization Chart, Staffing Plans, Succession Plans','HR / Quality Management','The organization shall determine and provide the persons necessary for the effective implementation of its QMS.'],
['7.1.4','Environment for Operation of Processes','ISO','Support','7','The organization must determine, provide and maintain the environment necessary for the operation of its processes and to achieve conformity of products and services.','1. What environmental factors (temperature, cleanliness, lighting, noise) are controlled in production — show monitoring records.\n2. How do you define acceptable environmental limits for critical processes?\n3. Are environmental conditions monitored at the point of use for quality-sensitive processes?\n4. What happens when environment goes out of control — show a reaction plan.\n5. How is the human environment (ergonomics, fatigue, safety) considered in process design?','Environmental Monitoring Records, Control Plans, Reaction Plans','Production / Quality','The organization shall determine, provide and maintain the environment necessary for the operation of its processes.'],
['7.1.5','Monitoring and Measurement Resources','ISO','Support','7','The organization must determine and provide monitoring and measurement resources to ensure valid results. Resources must be suitable, maintained, and fit for purpose.','1. Show me the master list of all measurement equipment used for product/process monitoring.\n2. How do you verify measurement equipment is fit for purpose before use in production?\n3. What happens when a gauge or instrument fails mid-shift — what is the reaction plan?\n4. How are new measurement requirements identified when new products or processes are introduced?\n5. Show me the last 3 months of calibration compliance rates for your measurement equipment.','Measurement Equipment Master List, Calibration Records, Gauge Fit-for-Purpose Assessment','Quality / Production','The organization shall determine and provide the resources needed to ensure valid and reliable results when monitoring or measurement is used.'],
['7.1.6','Organizational Knowledge','ISO','Support','7','The organization must determine the knowledge necessary for process operation and conforming products. Must maintain this knowledge, protect it, and consider how to acquire additional knowledge when needed.','1. How do you capture the knowledge of experienced employees before they leave or retire?\n2. Where is institutional knowledge stored — lessons learned, best practices, failure libraries?\n3. How is knowledge transferred to new employees — just training, or is there a structured knowledge sharing process?\n4. Show me a lesson learned that was documented from a customer complaint and applied to prevent recurrence.\n5. When new technology or customer requirement comes in, how do you acquire the necessary knowledge?','Lessons Learned Database, Knowledge Repository, Training Records, Failure Library','Quality / HR','The organization shall determine the knowledge necessary for the operation of its processes and maintain this knowledge.'],
['7.2','Competence','ISO','Support','7','Organization must determine required competence, ensure persons are competent, take actions to acquire needed competence, and retain documented evidence.','1. Show me the competency matrix — does it cover all quality-critical roles?\n2. For a newly hired quality inspector, what training/certification is required before working independently?\n3. When competency gaps are identified, what actions are taken — show a recent example.\n4. How do you verify training was effective — just attendance records or an assessment?\n5. How are competencies re-evaluated — what triggers a reassessment?','Competency Matrix, Training Records, Training Effectiveness Assessment, Qualification Records','HR / Quality','The organization shall determine the necessary competence of person(s) doing work under its control that affects the quality performance.'],
['7.4','Communication','ISO','Support','7','The organization must determine internal and external communications relevant to the QMS — what to communicate, when, with whom, how, and who communicates.','1. Show me your quality communication plan — how are quality issues communicated within the organization?\n2. How are customer complaints communicated to the production team — is it timely?\n3. How are quality policy and objectives communicated to all employees — not just managers?\n4. What mechanism exists for employees to raise quality concerns — is it effective?\n5. How are supplier quality issues communicated back to the supplier — what is the process?','Communication Plan, Quality Alerts, Supplier Communication Records, Toolbox Talk Records','All Departments','The organization shall determine the internal and external communications relevant to the QMS.'],
['7.5.1','Documented Information — General','ISO','Support','7','The organization must include the documented information required by the standard and additionally what is necessary for the effectiveness of the QMS.','1. Show me the list of all quality documents — is it complete and up to date?\n2. How do you determine what new documents are needed when a new process or product is introduced?\n3. Are all required IATF/ISO documents present and current?\n4. How do you manage documents that span multiple departments or processes?\n5. When was the last document audit conducted — what was the result?','Document Master List, Document Control Procedure, Quality Manual Index','Quality Management','The organization shall maintain documented information required by the standard and determined to be necessary for the effectiveness of the QMS.'],
['7.5.2','Creating and Updating Documented Information','ISO','Support','7','When creating and updating documented information, the organization must ensure appropriate identification and description, format and media, and review and approval for suitability and adequacy.','1. Show me a recently created or revised document — walk me through the creation/revision process.\n2. Who has authority to create, revise, and approve quality documents?\n3. How are documents formatted — is there a standard template?\n4. How do you prevent documents from being used before they are reviewed and approved?\n5. What is the typical turnaround time from document creation request to publication?','Document Control Procedure, Document Templates, Approval Records, Revision History','Quality Management','When creating and updating documented information, the organization shall ensure appropriate identification, format, and review and approval.'],
['7.5.3','Control of Documented Information','ISO','Support','7','Documented information required by the QMS must be controlled to ensure availability, suitability, and protection. This includes distribution, access, retrieval, and disposal.','1. How do you ensure workers have the CURRENT version of work instructions at the point of use — not an old print-out?\n2. How are obsolete documents removed from use — what is the process?\n3. Who has access to which documents — is there version control?\n4. How are external documents (customer standards, regulatory requirements) controlled?\n5. What happens if an employee finds conflicting versions of a document?','Document Control Procedure, Version Control Log, Obsolete Document Disposal Records','Quality Management','Documented information required by the QMS and by the standard shall be controlled to ensure availability, suitability, and protection.'],
['8.2.1','Customer Communication','ISO','Operation','8','Organization must implement a process to communicate with customers on product/service information, enquiries, orders, complaints, feedback, and contingency actions.','1. How do customers contact you to raise quality complaints — what channels are available?\n2. How quickly do you acknowledge a customer complaint — what is the SLA?\n3. How are customer requirements (including changes) communicated internally to production?\n4. How is customer feedback (satisfaction surveys, scorecards) collected and used?\n5. In a contingency (production line down, quality escape), how do you communicate with the customer?','Customer Communication Procedure, Complaint Log, Customer Satisfaction Records','Customer Quality / Sales','The organization shall implement a process for communicating with customers in relation to information, handling enquiries, customer feedback, and contingency actions.'],
['8.2.2','Determining Requirements for Products and Services','ISO','Operation','8','Organization must ensure it can meet the requirements for products and services offered to customers. Must also determine any statutory/regulatory requirements applicable.','1. Before accepting a new customer order, what quality checks do you perform on the requirements?\n2. How do you identify statutory and regulatory requirements applicable to your products?\n3. What happens if a customer requirement cannot be met — how is this escalated?\n4. How are supplier requirements and customer requirements aligned?\n5. Show me the most recently onboarded product — how were requirements captured?','Customer Requirements Review Record, Regulatory Requirements Register, Contract Review Log','Sales / Quality','The organization shall ensure that requirements for products and services are defined — including statutory, regulatory, and any additional requirements.'],
['8.2.3','Review of Requirements for Products and Services','ISO','Operation','8','The organization must review requirements before committing to supply products/services. Review must cover differences between previously stated and order requirements.','1. Show me the contract or order review process — who reviews, what is checked, and how is it documented?\n2. Has there ever been a case where you committed to supply without reviewing requirements — what happened?\n3. How do you handle changes to customer requirements after the contract is signed?\n4. When there are differences between quote requirements and order requirements, how are these resolved?\n5. Show me a recent example of an order review that identified a potential issue.','Order Review Records, Contract Review Checklist, Change Order Log','Sales / Quality','The organization shall review requirements for products and services before committing to supply.'],
['8.2.4','Changes to Requirements for Products and Services','ISO','Operation','8','When requirements change, the organization must ensure relevant documented information is amended and that relevant persons are made aware of the changed requirements.','1. How does a change in customer specification flow through to production — show the change control process.\n2. How quickly are engineering changes communicated to the shop floor after customer approval?\n3. What is the process for updating drawings, work instructions, and control plans when specs change?\n4. How do you prevent old specifications from being used after a change — what controls exist?\n5. Show me the last engineering change — trace it from customer request to updated documents on the floor.','Engineering Change Notice, Change Control Log, Document Update Records','Engineering / Quality','When requirements change, the organization shall amend relevant documented information and inform relevant persons.'],
['8.3.1','Design and Development Planning','ISO','Operation','8','Organization must establish, implement and maintain a design and development process. Planning must consider the nature, duration, complexity, required review stages, and responsibilities.','1. Show me the Design and Development Plan for a recent product — what stages are defined?\n2. Who is responsible for each phase of design and development — is it documented?\n3. How do you determine the review, verification, and validation stages appropriate for a specific design?\n4. How are customer CSRs incorporated into design planning?\n5. What is the process for design of experiments or prototype builds?','D&D Plan, APQP Timing Plan, Design Review Records','Engineering / Quality','The organization shall establish, implement and maintain a design and development process appropriate to ensure the subsequent provision of products and services.'],
['8.3.2','Design and Development Inputs','ISO','Operation','8','The organization must determine the inputs essential for the specific type of product/service being designed — including functional, performance, legal/regulatory requirements, applicable standards, and potential consequences of failure.','1. Show me the design input checklist for a recent product — what inputs were captured?\n2. How are safety and regulatory requirements identified as design inputs?\n3. How are previous design lessons learned incorporated as inputs for new designs?\n4. How are customer functional performance requirements translated into design specifications?\n5. Are design inputs reviewed and approved before proceeding to design activities?','Design Input Record, Requirement Specification, Applicable Standards List','Engineering / Quality','The organization shall determine the requirements essential for the specific type of design and development — including functional, performance, and regulatory requirements.'],
['8.3.3','Design and Development Controls','ISO','Operation','8','Organization must apply design and development controls to ensure results are defined, design reviews are conducted, design verification and validation are performed.','1. How many design review stages are conducted for a new product — who participates?\n2. At each design review, what evidence is examined and what is the approval criterion?\n3. How is design verification conducted — tests, calculations, simulations?\n4. How is design validation conducted — prototype builds, pilot runs, customer trials?\n5. What records are kept from each design review, verification, and validation activity?','Design Review Minutes, Verification Test Reports, Validation Reports, Design Sign-Off Records','Engineering / Quality','The organization shall apply design and development controls to ensure that results to be achieved are defined and reviews, verification and validation are conducted.'],
['8.3.4','Design and Development Outputs','ISO','Operation','8','Design outputs must meet input requirements, be adequate for subsequent processes, include monitoring/measurement requirements, and specify product characteristics essential for safe and proper use.','1. What are the design output documents for a new product — drawings, specifications, BOMs?\n2. How do design outputs link back to design inputs — is traceability maintained?\n3. How are product characteristics identified as critical or significant in the design output?\n4. How do design outputs define acceptance criteria for incoming inspection, in-process, and final inspection?\n5. How is the completeness of design outputs verified before releasing for production?','Engineering Drawings, Product Specifications, BOM, Control Plan Inputs, Test Specifications','Engineering / Quality','Design and development outputs shall meet the input requirements, be adequate for subsequent provision, include monitoring/measurement requirements, and define product characteristics.'],
['8.3.5','Design and Development Review','ISO','Operation','8','At suitable stages, systematic reviews of design and development must be performed to evaluate the ability of results to meet requirements and to identify problems and propose necessary actions.','1. Show me the record of the last formal design review — who attended and what was decided?\n2. What criteria must be met to pass each design review stage?\n3. How are open issues from design reviews tracked and resolved?\n4. Has a design review ever resulted in stopping or significantly redesigning a project — what happened?\n5. How are design reviews connected to APQP phase gate reviews?','Design Review Records, Open Issue Log, Design Review Agenda, Gate Review Reports','Engineering / Quality / Customer','At suitable stages, systematic reviews of design and development shall be performed to evaluate ability to meet requirements and identify problems.'],
['8.3.6','Design and Development Changes','ISO','Operation','8','The organization must identify, review, and control design and development changes made during or after product/service development, to prevent adverse impact.','1. How are design changes initiated — what triggers a design change request?\n2. Who has authority to approve design changes — what is the approval matrix?\n3. How do you assess the impact of a design change on previously verified/validated requirements?\n4. What customer approvals are required before implementing a design change?\n5. Show me the last design change — trace it from request to customer approval to shop floor implementation.','Design Change Request Form, Change Impact Assessment, Customer Approval Record, Updated Drawings','Engineering / Quality','The organization shall identify, review and control changes made during, or subsequent to, the design and development of products and services.'],
['8.4.1','Control of Externally Provided Processes, Products and Services','ISO','Operation','8','The organization must ensure that externally provided processes, products, and services conform to requirements. Must determine controls to apply to external providers.','1. Show me the approved supplier list — how many suppliers are on it and how was each approved?\n2. What criteria do you use to select a new supplier — is it just price, or does quality factor in?\n3. How are external providers informed of your quality requirements?\n4. What happens when a supplier delivers non-conforming material — show a recent case.\n5. How do you ensure outsourced processes meet the same standards as internal processes?','Approved Supplier List, Supplier Selection Records, Supplier Quality Requirements, Incoming Inspection Records','Supplier Quality / Purchasing','The organization shall ensure that externally provided processes, products and services conform to requirements.'],
['8.4.2','Type and Extent of Control of External Providers','ISO','Operation','8','The organization must define and apply controls on external providers, considering potential impact of externally provided processes/products on ability to meet requirements.','1. How do you categorize your suppliers by risk — which require more oversight?\n2. What controls do you apply to high-risk suppliers vs. low-risk suppliers?\n3. How do you verify externally provided products before releasing to production — incoming inspection process?\n4. Do you conduct supplier audits? Show me the last supplier audit report.\n5. How do you balance incoming inspection level against supplier performance history?','Supplier Risk Assessment, Incoming Inspection Procedure, Supplier Audit Reports, Control Plan','Supplier Quality','The organization shall define and apply evaluation criteria to external providers based on their ability to provide processes or products that meet requirements.'],
['8.4.3','Information for External Providers','ISO','Operation','8','The organization must communicate to external providers its requirements for processes, products, services, approval of products and processes, competence requirements, and control and monitoring requirements.','1. Show me the quality requirements document sent to a supplier — what does it cover?\n2. How do customer-specific requirements flow down to your suppliers?\n3. If a supplier must be IATF 16949 certified, how do you verify and monitor this requirement?\n4. How do you communicate changes in requirements to existing suppliers?\n5. What inspection or test records do you require suppliers to submit with each delivery?','Supplier Quality Requirements Document, Purchase Orders, Supplier Questionnaire, Quality Agreement','Supplier Quality / Purchasing','The organization shall communicate to external providers the requirements for processes, products and services to be provided — including quality requirements and monitoring requirements.'],
['8.5.1','Control of Production and Service Provision','ISO','Operation','8','Organization must implement production under controlled conditions: availability of documented information, use of suitable monitoring/measurement resources, implementation of monitoring/measurement activities.','1. Show me a work instruction for a critical operation — is it at the workstation?\n2. How do operators know what the acceptance criteria are for each operation?\n3. What monitoring activities happen during production — how often are checks performed?\n4. How is the production environment controlled for quality-sensitive operations?\n5. How do you ensure all production equipment is in proper working order before the start of a shift?','Work Instructions, Control Plans, In-Process Inspection Records, Equipment Pre-use Checks','Production / Quality','The organization shall implement production and service provision under controlled conditions.'],
['8.5.3','Identification and Traceability','ISO','Operation','8','The organization must use suitable means to identify outputs throughout production. Must identify the status of outputs with respect to monitoring/measurement requirements.','1. Show me how a product is identified from incoming raw material to finished goods — trace one part.\n2. How do you identify the inspection status of parts — conforming, non-conforming, hold?\n3. If a customer reports a field failure, how do you trace back to the specific batch and date of manufacture?\n4. How is identification maintained through heat treatment, plating, or other subcontracting operations?\n5. What happens to identification labels if they are damaged or lost during production?','Traceability Records, Batch/Lot Control Records, Identification Procedure, Production Log','Production / Quality','The organization shall use suitable means to identify outputs, identify status with respect to monitoring and measurement requirements, and control unique identification where traceability is a requirement.'],
['8.5.4','Property Belonging to Customers or External Providers','ISO','Operation','8','Organization must exercise care with customer/external provider property while it is under the organization\'s control, including tooling, equipment, intellectual property, and materials.','1. Show me the list of customer-supplied tooling, gauges, or materials — how are they controlled?\n2. How do you identify customer property in your facility to prevent loss or misuse?\n3. What happens if customer-supplied property is damaged, lost, or found unsuitable?\n4. How is customer intellectual property (drawings, specifications) protected against unauthorized use?\n5. What is the process for returning customer property — is it tracked?','Customer Property Register, Customer Property Agreement, Non-Conformance Report for Customer Property','Quality / Production / Logistics','The organization shall exercise care with property belonging to customers or external providers while it is under the organization\'s control or being used.'],
['8.5.5','Post-Delivery Activities','ISO','Operation','8','The organization must meet requirements for post-delivery activities associated with the nature of products/services, customer requirements, feedback from customers, and statutory/regulatory requirements.','1. What post-delivery support do you provide to customers — warranty, field service, spare parts?\n2. How are field failures investigated — show me the process from customer report to root cause analysis.\n3. Are warranty data analyzed for trends — show me the last warranty analysis report.\n4. How are field failure lessons learned fed back into design and production improvements?\n5. What contractual post-delivery commitments exist — how are they tracked and fulfilled?','Warranty Policy, Field Failure Reports, Warranty Analysis, Post-Delivery Support Records','Customer Quality / After-Sales','The organization shall meet requirements for post-delivery activities associated with products and services.'],
['8.6','Release of Products and Services','ISO','Operation','8','The organization must implement planned arrangements at appropriate stages to verify that product/service requirements have been met. Release must not proceed until arrangements are satisfactorily completed.','1. What is the final inspection process before product is released to the customer?\n2. Who has the authority to release product — is it documented?\n3. What documentation must be complete before product is released?\n4. Has product ever been released without completing all checks — what controls prevent this?\n5. How is customer authorization captured when they require approval before release?','Final Inspection Records, Release Authorization, Certificate of Conformance, Customer Release Approval','Quality / Production','The organization shall implement planned arrangements, at appropriate stages, to verify that product and service requirements have been met.'],
['9.1.1','Monitoring, Measurement, Analysis and Evaluation — General','ISO','Performance Evaluation','9','Organization must determine what to monitor and measure, the methods, when to perform, and when to analyze/evaluate. Must retain documented evidence of results.','1. Show me the complete list of quality KPIs — how were they selected?\n2. For each KPI, what is the measurement method, frequency, and target?\n3. Who is responsible for collecting, analyzing, and reporting each KPI?\n4. How are KPI trends analyzed — is there trend analysis beyond just current month?\n5. When a KPI misses target, what is the escalation and action process?','Quality KPI Dashboard, KPI Monitoring Plan, Management Review Input Reports','Quality Management','The organization shall determine what needs to be monitored and measured, the methods, when it shall be performed and analyzed, and shall retain documented evidence of results.'],
['9.1.3','Analysis and Evaluation','ISO','Performance Evaluation','9','The organization must analyze and evaluate appropriate data and information to evaluate performance, identify improvement opportunities, and assess QMS effectiveness.','1. Show me the last quarterly quality analysis report — what data was analyzed?\n2. How do you analyze customer satisfaction trends — what tools are used?\n3. How do you analyze supplier performance data — PPM, on-time delivery, quality issues?\n4. How is the effectiveness of corrective actions evaluated statistically or systematically?\n5. What QMS improvements were made in the last 12 months based on data analysis?','Quality Analysis Reports, Trend Charts, Supplier Performance Reports, Corrective Action Effectiveness Reviews','Quality Management','The organization shall analyze and evaluate appropriate data and information arising from monitoring and measurement.'],
['9.2.2','Internal Audit Programme','ISO','Performance Evaluation','9','The organization must plan, establish, implement, and maintain an audit programme including frequency, methods, responsibilities, planning requirements, and reporting.','1. Show me the annual internal audit plan — does it cover all QMS processes and clauses?\n2. How are audit frequency and scope determined — is risk used as a basis?\n3. Who plans the audit schedule — how far in advance are auditors informed?\n4. How do you ensure auditors are objective and impartial — are they auditing their own area?\n5. What happens if an audit reveals a major systemic issue — is there an escalation plan?','Annual Audit Plan, Audit Schedule, Auditor Independence Matrix, Audit Programme Review','Internal Audit / Quality','The organization shall establish, implement and maintain an audit programme including frequency, methods, responsibilities, planning requirements and reporting.'],
['9.3.2','Management Review Inputs','ISO','Performance Evaluation','9','Management review must include inputs on customer satisfaction/feedback, QMS objectives achievement, process performance/conformity, NCR/corrective actions, audit results, supplier performance, and continual improvement opportunities.','1. Show me the last management review input report — what data was presented?\n2. Was customer satisfaction data (PPM, complaints, scorecard) included?\n3. Were all audit findings and their closure status presented?\n4. How is supplier performance summarized for management review?\n5. Were opportunities for improvement identified and assigned during the review?','Management Review Input Report, Management Review Agenda, KPI Summary','Quality Management / Top Management','Management review shall include customer satisfaction, QMS objective achievement, process performance, NCR/CA status, audit results, supplier performance, resource adequacy, and improvement opportunities.'],
['9.3.3','Management Review Outputs','ISO','Performance Evaluation','9','Management review must produce outputs that include decisions and actions related to improvement opportunities, need for QMS changes, and resource needs.','1. Show me the management review output — what decisions were made and what actions were assigned?\n2. Who is responsible for each action from the management review — are there clear owners and deadlines?\n3. How are management review actions tracked to completion — show the follow-up mechanism.\n4. Has management review ever identified a need for major QMS change — what was it?\n5. How are management review outputs communicated to relevant functions?','Management Review Minutes, Action Plan, Follow-up Records','Top Management / Quality','The outputs of the management review shall include decisions and actions related to opportunities for improvement, need for QMS changes, and resource needs.'],
['10.1','Continual Improvement — General','ISO','Improvement','10','The organization must continually improve the suitability, adequacy, and effectiveness of the QMS. Must consider results of analysis, evaluation, and management review.','1. What formal continual improvement initiatives are running in quality — what methodology is used?\n2. Show me 3 improvements made in the last 12 months that resulted in measurable quality gains.\n3. How does the Kaizen or CI program connect to quality objectives?\n4. How are improvement ideas from shop floor employees captured and acted upon?\n5. How do you ensure improvements are sustained and not just short-term fixes?','CI Project Register, Kaizen Records, Improvement Tracking Log','All Departments','The organization shall continually improve the suitability, adequacy and effectiveness of the QMS.'],
['10.2.1','Nonconformity and Corrective Action — Reaction','ISO','Improvement','10','When a nonconformity occurs, the organization must react to control and correct it, deal with consequences, evaluate for causes, implement actions, review effectiveness, and update risk.','1. When a nonconforming product is found, what is the immediate reaction — containment and sorting?\n2. How is the customer notified when a potential escape has occurred?\n3. After containment, how long does it take to start the root cause investigation?\n4. Who has authority to release contained material — is it documented?\n5. Show me a recent major nonconformity — walk me through the complete reaction process.','NCR Log, Containment Records, Customer Notification Records, 8D Reports','Quality / Production','When a nonconformity occurs, the organization shall react to control and correct it, deal with the consequences, and evaluate the need for corrective action.'],
['10.2.2','Nonconformity and Corrective Action — System Actions','ISO','Improvement','10','Corrective actions must be appropriate to the effects of the nonconformity. Must update risks/opportunities, make QMS changes if needed, and ensure corrective action effectiveness.','1. How do you ensure corrective actions address the ROOT CAUSE, not just the symptom?\n2. Show me a corrective action that required a QMS change — what changed and why?\n3. How do you verify that a corrective action was effective — what is the verification period?\n4. When similar nonconformities occur in other processes/areas, how is the CA horizontally deployed?\n5. How are CAs linked back to the Risk Register — is risk re-evaluated after CA?','Corrective Action Register, Root Cause Analysis Records, Effectiveness Review, Risk Register Update','Quality Management','The organization shall implement corrective actions appropriate to the effects of nonconformities encountered, and evaluate the effectiveness of actions taken.'],
// ── IATF 16949 supplemental clauses ──────────────────────────────────────
['5.3.1','Organizational Roles — Quality Responsibility and Authority','IATF','Leadership','5','Customer representative must be designated with authority to ensure customer requirements are addressed — including special characteristics, quality objectives, and training.','1. Who is the designated Customer Representative — is this documented in the org chart?\n2. How does the CR ensure customer-specific requirements are communicated to all relevant functions?\n3. How does the CR ensure CS requirements are included in APQP, PFMEA, control plans?\n4. What is the CR\'s escalation authority when there is a conflict between quality and delivery?\n5. Show me evidence that the CR participated in the last APQP review for a new product.','Customer Representative Appointment Letter, CSR Register, APQP Records','Quality Management','Top management shall assign personnel with the responsibility and authority to ensure customer requirements are met — including selection of special characteristics.'],
['6.1.2.1','Risk Analysis — IATF Supplemental','IATF','Planning','6','The organization shall include in its risk analysis lessons learned from product recalls, warranty analysis, field returns, and customer complaints to assess potential risk to product safety and regulatory compliance.','1. How are warranty failures and field returns systematically analyzed for risk inputs?\n2. Show me how a past recall or field issue was used as a risk input for a new product PFMEA.\n3. Is there a formal risk analysis that considers product safety and regulatory risks?\n4. How are regulatory requirements (FMVSS, EMC, etc.) captured as risk inputs?\n5. What is the escalation path when a risk analysis identifies a potential safety risk?','Warranty Analysis Reports, Field Return Analysis, PFMEA with Risk Linkage, Safety Risk Register','Quality / Engineering','The organization shall include in its risk analysis the lessons learned from product recalls, field returns and warranty claims.'],
['6.1.2.2','Preventive Actions','IATF','Planning','6','The organization must have a process for preventive actions — identifying potential nonconformities and their causes and taking action to prevent occurrence, including updating documentation.','1. Describe your preventive action process — how is it different from corrective action?\n2. Show me 3 preventive actions initiated in the last 12 months — what triggered them?\n3. How do PFMEA risk reduction actions get tracked as preventive actions?\n4. How are lessons learned from other plants or industry used to initiate preventive actions?\n5. How do you document and close out preventive actions?','Preventive Action Register, PFMEA Action Plans, Lessons Learned Database','Quality Management','The organization shall have a process for preventive action to prevent occurrence of nonconformities.'],
['6.2.2.1','Quality Objectives — IATF Supplemental','IATF','Planning','6','Quality objectives must be established at each relevant function, level, and process. Must include customer-specific quality performance requirements.','1. Show me quality objectives at function level — not just company level. Are department-specific targets set?\n2. Do quality objectives include customer-specific metrics (PPM, warranty, OTD)?\n3. Are quality objectives linked to individual performance reviews or incentive plans?\n4. How frequently are quality objectives reviewed within the year — monthly, quarterly?\n5. When a customer scorecard shows poor performance, is a quality objective set to address it?','Quality Objectives Register by Function, Customer Scorecard, Department KPI Dashboard','Quality Management','The organization shall establish quality objectives at each relevant function, level and process — including customer-specific quality performance requirements.'],
['7.1.3.1','Plant, Facility and Equipment Planning','IATF','Support','7','The organization must use a multidisciplinary approach for developing plant layouts that optimize material flow, handling, and use of floor space. Must include methods to evaluate risk to achieve production requirements.','1. Show me the plant layout — how was it developed and when was it last reviewed?\n2. Was a multidisciplinary team involved in the plant layout — who participated?\n3. How is material flow analyzed to minimize transport and handling risk?\n4. When adding new equipment or processes, what planning methodology is used?\n5. How are ergonomic and safety factors incorporated into plant and facility planning?','Plant Layout Drawings, Facility Planning Records, Material Flow Analysis, Ergonomic Assessment','Engineering / Production / Quality','The organization shall use a multidisciplinary approach for developing plant layouts, including the evaluation of risks to quality.'],
['7.1.4.1','Environment — IATF Supplemental','IATF','Support','7','The organization must have a process for personnel safety and must have controls to protect product quality from environmental hazards including contamination.','1. Show me the product cleanliness/contamination control procedures — especially for critical products.\n2. How are foreign material exclusion programs managed on the shop floor?\n3. What environmental hazards have been identified that could affect product quality?\n4. How is the control of environmental conditions verified and recorded?\n5. Are there any products where contamination would be a safety risk — how is this managed?','Environmental Control Procedures, Contamination Control Records, ESD Control Documentation','Production / Quality','The organization shall maintain a process for managing personnel safety and the product quality environment including contamination controls.'],
['7.1.5.1.2','Calibration/Verification Records','IATF','Support','7','Calibration records must include equipment ID, revision status, out-of-tolerance conditions, assessment of measurement validity, notification of customer if suspect product was shipped, and statements of conformity after calibration.','1. Show me a calibration record — does it include all required fields including out-of-tolerance history?\n2. When a gauge is found out of tolerance, who decides if shipped product is suspect?\n3. Has there been a case where suspect product was shipped due to out-of-tolerance gauge — how was customer notified?\n4. How are calibration labels applied to equipment to show calibration status?\n5. What happens when calibration is due and the equipment cannot be taken off line?','Calibration Certificate, Out-of-Tolerance Notification, Customer Notification Records, Recall Assessment','Quality / Metrology','Calibration records shall include equipment ID, out-of-tolerance findings, product suspect assessment, and customer notification when applicable.'],
['7.1.5.2','Measurement Systems Analysis — Supplemental','IATF','Support','7','MSA requirements apply to all measurement systems referenced in the control plan. The organization must maintain appropriate records and re-perform MSA when equipment or measurement process changes.','1. Show me the MSA plan — does it cover all gauges in the control plan?\n2. For variable gauges, show me the GRR results — are all %GRR values within acceptance limits?\n3. For attribute gauges, show me the Attribute Agreement Analysis results.\n4. When a gauge was replaced or repaired, was MSA re-performed?\n5. Who performs MSA studies — are they trained and competent in MSA methodology?','MSA Plan, GRR Reports, Attribute Agreement Analysis, Gauge Replacement Records','Quality / Metrology','Statistical studies shall be performed to analyze the variation in results for each measurement system referenced in the control plan.'],
['7.1.5.3.2','External Laboratory Requirements','IATF','Support','7','When using external labs for testing, the lab must be accredited to ISO/IEC 17025 or national equivalent. Lab scope must include the specific test being performed.','1. Show me the list of external labs you use — are all accredited to ISO 17025?\n2. For each test performed externally, is the test in the lab\'s accreditation scope?\n3. Have you ever used a non-accredited lab — if so, was there customer authorization?\n4. How do you verify lab accreditation status before sending samples?\n5. How are external lab test reports retained and linked to the relevant product/complaint?','External Lab Accreditation Certificates, Test Request Records, Test Reports, Lab Qualification Records','Quality','External labs used for inspection, test or calibration services shall be accredited to ISO/IEC 17025.'],
['7.2.1','Competence — Supplemental (IATF)','IATF','Support','7','The organization must maintain documented processes for verifying that operator competence is maintained on an ongoing basis, including reaction plans when competency is not demonstrated.','1. How do you verify operator competence on an ongoing basis — not just at hire?\n2. Show me the re-certification or re-qualification process for critical quality operations.\n3. If an operator fails a competency check, what is the immediate reaction — can they continue operating?\n4. How do you track competency expiry dates — what happens when they lapse?\n5. Are temporary or agency workers included in competency verification?','Operator Competency Verification Records, Qualification Matrix, Re-certification Records','HR / Quality / Production','The organization shall maintain documented processes for verifying that operator competence is maintained — including reaction plans when competency requirements are not met.'],
['7.2.2','Competence — On-the-Job Training','IATF','Support','7','The organization must provide on-the-job training for any employees whose work can affect quality, including temporary employees and agency workers.','1. How is on-the-job training structured — is there a defined training program for each role?\n2. How are temporary/agency workers trained — do they receive the same training as permanent staff?\n3. How is training specific to customer requirements conducted — are CSRs covered in OJT?\n4. Who signs off that OJT is complete and the employee is qualified to work independently?\n5. Show me the OJT record for a recently hired quality inspector.','OJT Training Records, Training Completion Sign-Off, CSR Training Records, Agency Worker Training Log','HR / Quality / Production','The organization shall provide on-the-job training for personnel in any new or modified responsibilities affecting product quality including temporary staff and agency workers.'],
['7.2.4','Competence — Awareness of Consequences','IATF','Support','7','The organization must have a documented process for motivating employees to achieve quality objectives, including awareness of the consequences of noncompliance with quality system requirements.','1. How do employees know about the consequences of quality failures — customer returns, shutdowns, recalls?\n2. Show me the communication or training that covers consequences of non-compliance.\n3. How are quality problems communicated back to the operators who may have caused them?\n4. Is there a formal recognition system for quality performance — how are employees motivated?\n5. How do you measure employee awareness and engagement with quality objectives?','Quality Awareness Training Records, Communication Records, Recognition Program Documentation','HR / Quality / Management','The organization shall have a documented process for motivating employees to achieve quality objectives — including awareness of the consequences of noncompliance.'],
['7.3.1','Awareness — Supplemental (IATF)','IATF','Support','7','The organization must maintain documented information on the quality policy, quality objectives, and their contribution to product conformity, safety, and quality system effectiveness.','1. How is the quality policy communicated and understood by all employees — including shop floor workers?\n2. Can operators explain what the quality policy means for their daily work?\n3. How are quality objectives communicated to all levels — not just managers?\n4. How do operators know their role in achieving quality objectives?\n5. When was the last time employees were tested on quality policy awareness?','Quality Policy Communication Records, Awareness Training Records, Employee Awareness Assessment','Quality / HR','The organization shall maintain documented information on quality policy, objectives, and employee contribution to product conformity and safety.'],
['7.4.1','Customer Communication — Supplemental','IATF','Support','7','The organization must have a process to communicate quality information relevant to customers — including customer-specific requirements, escape notifications, warranty data, and PPAP status.','1. How and when are customers notified of a potential quality escape?\n2. What is the process for communicating PPAP status and timing to customers?\n3. How are customer-specific requirements communicated internally to all affected functions?\n4. When PPAP is delayed or rejected, how is this communicated to the customer and escalated internally?\n5. Show me a recent customer notification for a quality escape — what was communicated and when?','Customer Notification Procedure, Escape Notification Records, PPAP Communication Log','Customer Quality / Sales / Quality','The organization shall have a process to communicate quality information to customers including escape notifications, warranty data, and PPAP status.'],
['7.5.3.2','Document Control — Supplemental (IATF)','IATF','Support','7','Engineering specifications and changes must be reviewed within a specific time period (generally stated in CSRs). A documented process must exist to distribute and implement engineering changes.','1. What is your timing target for reviewing and implementing customer engineering changes?\n2. Show me the process for receiving, reviewing, and distributing an engineering change from a customer.\n3. How do you verify that engineering changes are reflected in all affected documents (drawings, WI, CP, PFMEA)?\n4. How long does it take from customer engineering change approval to implementation on the shop floor?\n5. What happens if an engineering change requires a production trial — how is this managed?','Engineering Change Control Procedure, Change Timing Records, ECN Log, Updated Documents','Engineering / Quality','A documented process shall exist for reviewing and implementing changes in engineering specifications — with timely distribution.'],
['8.1.1','Operational Planning — Supplemental (IATF)','IATF','Operation','8','Organization must plan, implement, control, maintain, and improve processes needed for realization. Planning must consider criteria for process operation and the risks identified in manufacturing process risk analysis.','1. How is manufacturing process risk analysis (PFMEA) used in operational planning?\n2. How are control plans developed and linked to PFMEA risk levels?\n3. When a new product is launched, how do you ensure all manufacturing controls are in place before SOP?\n4. How are process parameters (speed, temperature, pressure) established and controlled?\n5. What is the process for ensuring all process controls are verified before mass production?','Control Plan, PFMEA, Process Flow Diagram, Pre-Launch Verification Records','Engineering / Quality / Production','The organization shall plan, implement, control, maintain and improve processes needed for product realization — considering manufacturing process risk analysis.'],
['8.1.2','Confidentiality','IATF','Operation','8','The organization must ensure the confidentiality of customer-contracted products and projects under development including product information to be protected.','1. How do you protect customer-confidential product information — drawings, specifications, project plans?\n2. Are there NDAs or confidentiality agreements in place with customers?\n3. How is access to confidential customer information controlled — who can access it?\n4. How do you prevent confidential information from leaving the organization — USB, email controls?\n5. When an employee leaves, how is access to confidential information revoked?','NDA Agreements, Information Security Policy, Access Control Records, Confidentiality Training Records','Quality / HR / IT','The organization shall ensure confidentiality of customer-contracted products and projects under development.'],
['8.2.1.1','Customer Communication — IATF Supplemental','IATF','Operation','8','Must include communication of in-plant problem solving results and activities to customers, must be in customer-required language.','1. Are 8D or problem solving reports submitted to customers in the language they require?\n2. How quickly are customers informed of problem-solving progress — at what milestones?\n3. When a complaint is not resolved by the initial D3 containment, how is this communicated to the customer?\n4. How do you track customer acknowledgment of your 8D or CAPA submissions?\n5. What happens if a customer rejects your 8D report — what is the escalation process?','8D Report Submission Records, Customer Acknowledgment Records, Language Requirements Register','Customer Quality / Quality','Communication of in-plant problem-solving results and activities must be provided to customers — including in the customer\'s required language.'],
['8.2.2.1','Determining Requirements — Supplemental (IATF)','IATF','Operation','8','The organization must have processes to communicate all applicable statutory and regulatory requirements to customers.','1. How do you identify and track statutory and regulatory requirements applicable to your products?\n2. How are regulatory requirements communicated to customers — proactively or only on request?\n3. How do you ensure your internal processes comply with all applicable regulations (REACH, RoHS, etc.)?\n4. When a regulation changes, how does this flow into your process — from identification to implementation?\n5. Are there products shipped to multiple regions with different regulatory requirements — how is this managed?','Regulatory Requirements Register, Regulatory Compliance Certificates, Customer Communication Records','Quality / Engineering / Regulatory','The organization shall have a process to communicate applicable statutory and regulatory requirements to customers.'],
['8.2.3.1.1','Customer-Authorized Special Characteristics','IATF','Operation','8','Requirements agreed upon with customers for special characteristics must be maintained and applied throughout the organization — from design through manufacturing control plans.','1. Show me the special characteristics identified for your most complex product — how were they selected?\n2. Are all customer-designated special characteristics included in the PFMEA and control plan?\n3. How are special characteristics communicated to operators — are they highlighted on WI and control plans?\n4. What additional controls are applied to special characteristics (100% inspection, SPC, error-proofing)?\n5. When a new special characteristic is identified mid-production, how is the control plan updated?','Special Characteristics Register, PFMEA with SC flagging, Control Plan with SC, Work Instructions with SC highlighted','Engineering / Quality','Customer-authorized special characteristics shall be maintained and applied throughout the organization\'s processes.'],
['8.2.3.1.2','Feasibility Review','IATF','Operation','8','The organization must review new manufacturing/design feasibility before accepting the contract — including manufacturing feasibility, quality capability, and timing.','1. Show me the feasibility review process and record for a recently accepted customer program.\n2. What factors are assessed in feasibility — capacity, tooling, quality, logistics?\n3. Who participates in feasibility reviews — is it a cross-functional team?\n4. Has a feasibility review ever resulted in declining a customer program — what happened?\n5. Are feasibility reviews conducted when engineering changes significantly alter the product or process?','Feasibility Review Form, Cross-Functional Feasibility Sign-Off, Program Acceptance Records','Sales / Engineering / Quality / Production','A manufacturing feasibility review shall be conducted before contract acceptance — including cross-functional assessment of capability.'],
['8.2.4.1','Customer Engineering Approvals','IATF','Operation','8','Where products are designed by the customer, the organization must obtain customer engineering approvals before production — and maintain records of such approvals.','1. Show me evidence of customer engineering approval for a current production product.\n2. Where customer engineering approval is required, how is it tracked — is there a master register?\n3. How do you ensure production does not start before customer approval is received?\n4. If interim or conditional approval is given, how are the conditions managed?\n5. How long are customer engineering approval records retained?','Customer Approval Records, Engineering Approval Register, PPAP Approval Letters','Engineering / Quality','Where products are customer-designed, the organization shall obtain customer engineering approvals for such products.'],
['8.3.1.1','Design and Development Planning — Supplemental','IATF','Operation','8','Design and development planning shall use a multidisciplinary approach including risk analysis using tools such as DFMEA, and shall include requirements for design verification and validation plans.','1. Show me the multidisciplinary team for a recent D&D project — who was included and when did they engage?\n2. Is DFMEA conducted for all new designs — show me a recent DFMEA.\n3. How is DVP&R used to plan design testing?\n4. How does APQP structure the design and development phases for a new product?\n5. How are lessons learned from previous designs incorporated into current design planning?','Multidisciplinary Team Records, DFMEA, DVP&R, APQP Plan, Lessons Learned','Engineering / Quality','Design and development planning shall use a multidisciplinary approach including risk analysis (DFMEA) and requirements for design verification and validation.'],
['8.3.2.1','Design and Development Inputs — Product Design','IATF','Operation','8','Design inputs shall include customer requirements — including special characteristics, applicable government, safety and environmental standards, and previous DFMEA learnings.','1. Show me the design input register for a recent product — are customer CSRs included?\n2. How are government safety standards (e.g. FMVSS, ECE) captured as design inputs?\n3. How are lessons from previous DFMEAs used as design inputs for similar products?\n4. Are environmental requirements (REACH, RoHS) included as design inputs?\n5. How do you ensure all required design inputs are reviewed and approved before design begins?','Design Input Register, Regulatory Requirements List, Previous DFMEA Lessons Learned, Customer CSR Register','Engineering / Quality','Design and development inputs shall include customer requirements including special characteristics, government/safety/environmental standards, and historical DFMEA learnings.'],
['8.3.2.2','Design Inputs — Manufacturing Process','IATF','Operation','8','Manufacturing process design inputs shall include design outputs, targets for productivity, quality process capability, costing, and customer requirements, including PFMEA.','1. How do manufacturing process design inputs link to the product design outputs?\n2. Show me how productivity and process capability targets are set as inputs for manufacturing process design.\n3. How is cost per unit built into manufacturing process design considerations?\n4. How does PFMEA input into manufacturing process design decisions?\n5. How do customer-specific requirements affect manufacturing process design?','Manufacturing Process Design Input Register, PFMEA, Process Capability Targets, Cost Analysis','Manufacturing Engineering / Quality','Manufacturing process design inputs shall include product design outputs, productivity targets, process capability targets, costing, and customer requirements including PFMEA.'],
['8.3.2.3','Special Characteristics in Design','IATF','Operation','8','The organization must identify special characteristics during product and process design activities — including on drawings, PFMEAs, control plans, and work instructions.','1. How are special characteristics identified — who makes this determination?\n2. Show me a product drawing — are special characteristics clearly marked with the required symbol?\n3. Are special characteristics consistently identified across the drawing, PFMEA, control plan, and WI?\n4. How does the organization handle a special characteristic that is very difficult to control?\n5. When customer changes a special characteristic classification, how is this communicated and implemented?','Product Drawings with SC marking, PFMEA, Control Plan, Work Instructions — all with consistent SC symbols','Engineering / Quality','Special characteristics shall be identified on drawings, PFMEAs, control plans and operator instructions — with consistent symbols.'],
['8.3.3.1','Design Validation — Supplemental (IATF)','IATF','Operation','8','Design validation shall be performed in accordance with customer requirements including any testing that is part of design verification and validation planning.','1. Show me the design validation plan for a recent product — what tests were conducted?\n2. Were customer-specific validation requirements incorporated into the DVP?\n3. How do you ensure design validation is complete before recommending PPAP submission?\n4. Were any validation failures encountered — how were they resolved?\n5. How are validation results linked to the PPAP package?','Design Validation Test Reports, DVP&R, PPAP Package with Validation Data','Engineering / Quality','Design validation shall be performed in accordance with customer requirements and shall be completed prior to production approval.'],
['8.3.3.2','Prototype Programme','IATF','Operation','8','When required by the customer, the organization must have a prototype programme. Must use same suppliers, tooling, and manufacturing process as production wherever possible.','1. When customers require prototype builds, what is your prototype programme process?\n2. How are prototype parts identified and controlled to prevent mixing with production parts?\n3. Are prototype suppliers aligned with intended production suppliers — if not, what is the justification?\n4. How are prototype test results documented and linked to design validation?\n5. How are prototype learnings fed back into design changes before production tooling is released?','Prototype Plan, Prototype Build Records, Prototype Test Results, Prototype-to-Production Differences Log','Engineering / Quality','Where required, the organization shall have a prototype programme using same suppliers, tooling and manufacturing processes as planned for production where possible.'],
['8.3.4.1','Monitoring of D&D Process','IATF','Operation','8','The organization shall define and implement methods for monitoring the design and development process to confirm that achievement of design targets is planned and tracked.','1. How is design and development progress tracked against the APQP timing plan?\n2. Who monitors design milestones — is there a program manager or equivalent?\n3. What dashboard or system is used to track D&D open issues?\n4. When a milestone is at risk, how is this escalated and what corrective action is taken?\n5. How are design and development issues escalated to top management when required?','APQP Timing Plan, Open Issues Tracker, Program Status Report, Milestone Review Records','Engineering / Quality / Program Management','The organization shall define and implement methods for monitoring and controlling design and development activities against plans.'],
['8.3.5.1','Design Outputs — Product Design','IATF','Operation','8','Product design outputs shall include DFMEA, reliability results, product special characteristics, updated system FMEA, or design verification results and updated design reviews.','1. Show me the DFMEA for a current product — is it linked to the control plan?\n2. How are reliability targets (B10, MTTF) established and verified for products?\n3. Are special characteristics in the DFMEA consistent with those in the control plan?\n4. How are DFMEA results used to update manufacturing process risk analysis?\n5. When design changes occur, how are the DFMEA and related outputs updated?','DFMEA, Reliability Test Reports, Special Characteristics List, Updated Control Plan','Engineering / Quality','Product design outputs shall include DFMEA, reliability results, product special characteristics, and updated design reviews.'],
['8.3.5.2','Design Outputs — Manufacturing Process Design','IATF','Operation','8','Manufacturing process design outputs shall include PFMEA, control plan, process flow diagram, work instructions, process approval criteria, and quality, reliability, and productivity targets.','1. Show me the manufacturing process design outputs for a product — PFMEA, control plan, and process flow diagram.\n2. How do you ensure the control plan covers all process steps in the process flow diagram?\n3. Are process approval criteria (1st off approval, setup approval) defined in the manufacturing process outputs?\n4. How are productivity and quality targets reflected in the manufacturing process design?\n5. When a manufacturing process changes, are all related outputs (PFMEA, CP, WI) updated?','PFMEA, Control Plan, Process Flow Diagram, Work Instructions, Process Approval Criteria','Engineering / Quality','Manufacturing process design outputs shall include PFMEA, control plan, process flow diagram, work instructions, and process approval criteria.'],
['8.3.6.1','Design and Development Changes — Supplemental','IATF','Operation','8','Design and development changes shall include assessment of effects on fit, form, function, performance, reliability, and product safety. Customer notification and approval shall be obtained where required.','1. Show me the design change impact assessment for a recent change — what dimensions were evaluated?\n2. When does a design change require customer notification and how is this determined?\n3. Have you ever needed customer PPAP re-approval due to a design change — show an example?\n4. How do you ensure that all downstream documents are updated when a design change occurs?\n5. How are design changes controlled for products already in the field vs. new production?','Design Change Impact Assessment, Customer Notification Records, Updated PPAP Package, ECN Register','Engineering / Quality','Design and development changes shall include an assessment of the impact on fit, form, function, performance, durability, and product safety.'],
['8.4.1.1','Supplier Selection Process','IATF','Operation','8','The organization must have a documented supplier selection process — including risk assessment, quality system requirements, delivery performance, and financial stability.','1. Show me the supplier selection procedure — what criteria are evaluated?\n2. How is supplier quality system (IATF, ISO 9001) included in selection criteria — is it mandatory?\n3. How do you assess a new supplier\'s financial stability before approving?\n4. When customer-directed suppliers are used, what quality controls do you still apply?\n5. How long does supplier approval typically take — what are the stages?','Supplier Selection Procedure, Supplier Evaluation Report, Supplier Approval Records','Supplier Quality / Purchasing','The organization shall have a documented supplier selection process including risk assessment, quality system requirements, delivery performance, and financial assessment.'],
['8.4.1.2','Customer-Directed Sources','IATF','Operation','8','Where directed by the customer to use specific suppliers (customer-directed sources), the organization retains responsibility for quality. Must communicate requirements to directed sources.','1. Do you have any customer-directed suppliers — who are they and what do they supply?\n2. How do you communicate quality requirements to customer-directed suppliers?\n3. What controls do you apply to incoming material from customer-directed suppliers?\n4. When a customer-directed supplier has a quality problem, how is this escalated?\n5. How do you handle the situation where a customer-directed supplier delivers non-conforming material?','Customer-Directed Supplier Register, Quality Requirements Communication Records, Incoming Inspection Records','Supplier Quality','Where the customer directs the use of specific sources, the organization is not absolved of responsibility for quality of externally provided products.'],
['8.4.2.1','Supplier Quality System Development','IATF','Operation','8','The organization must require its suppliers to have ISO 9001 or IATF 16949 certification as appropriate, and must have a process to develop supplier quality systems toward these standards.','1. What percentage of your direct material suppliers are IATF 16949 or ISO 9001 certified?\n2. For suppliers not yet certified, what is the development plan — timeline and milestones?\n3. How do you support suppliers in developing their QMS — audits, training, resources?\n4. Are critical or high-risk suppliers prioritized for QMS development?\n5. Show me a supplier development plan for a non-certified supplier.','Supplier Certification Register, Supplier Development Plan, Supplier Development Audit Records','Supplier Quality','The organization shall have a process to develop the quality management systems of its suppliers toward ISO 9001 or IATF 16949 certification.'],
['8.4.2.2','Supplier Monitoring','IATF','Operation','8','The organization must have a process to monitor supplier performance including PPM quality performance, delivery performance, customer disruptions, special status customer notifications, and warranty returns.','1. Show me the supplier performance scorecard — what metrics are tracked and how often?\n2. What are the PPM and OTD targets for suppliers — and which suppliers are below target?\n3. When a supplier receives a poor scorecard, what is the consequence — escalation, development plan?\n4. How are supplier disruptions factored into supplier scorecard?\n5. How is supplier scorecard shared with the supplier and what is the response expectation?','Supplier Scorecard, Supplier Performance Database, Corrective Action Requests to Suppliers','Supplier Quality','The organization shall have a process to monitor supplier performance — including quality PPM, delivery performance, and customer disruption incidents.'],
['8.4.2.3','Second-Party Audits','IATF','Operation','8','The organization must have a risk-based process to determine type and frequency of second-party audits. Audit results shall be used as input to supplier scorecard and development activities.','1. Show me the second-party audit schedule — which suppliers are audited and how frequently?\n2. How is audit frequency determined — is it risk-based (performance, criticality, certification status)?\n3. Who conducts supplier audits — are the auditors trained and qualified?\n4. Show me the last supplier audit report — what were the findings and what actions were taken?\n5. How are supplier audit results linked to the supplier scorecard and development plan?','Supplier Audit Schedule, Supplier Audit Reports, Supplier Audit Action Plans, Auditor Qualification Records','Supplier Quality','The organization shall have a risk-based process to determine the type and frequency of second-party audits — with results linked to supplier scorecard.'],
['8.4.2.5','Supplier Development Prioritization','IATF','Operation','8','The organization shall prioritize supplier quality system development based on risk analysis including supplier\'s performance levels, quality issues, and customer disruption potential.','1. How do you prioritize which suppliers to develop — what risk factors are considered?\n2. Are high-risk suppliers (sole source, high PPM, no IATF cert) receiving more development attention?\n3. Show me the supplier risk ranking — how many suppliers are in each risk tier?\n4. What development activities are specifically assigned to high-priority suppliers?\n5. How do you measure whether supplier development is working — what outcomes do you track?','Supplier Risk Ranking, Supplier Development Priority List, Development Activity Records','Supplier Quality','The organization shall prioritize supplier development based on risk analysis of the supplier\'s performance levels and potential for customer disruption.'],
['8.4.3.1','Information to Suppliers — Supplemental','IATF','Operation','8','The organization shall communicate applicable statutory and regulatory requirements and customer-specific requirements to its suppliers.','1. Show me the supplier quality manual or requirements document — does it include all applicable CSRs?\n2. How do you ensure suppliers are aware of regulatory requirements (REACH, RoHS, conflict minerals)?\n3. When a new CSR is received from a customer, how is this communicated to suppliers?\n4. How do you verify that suppliers have acknowledged and implemented communicated requirements?\n5. Are there requirements for suppliers to flow down these requirements to their sub-suppliers?','Supplier Quality Manual, CSR Flow-Down Records, Regulatory Requirements Communication','Supplier Quality','The organization shall communicate applicable statutory and regulatory requirements and customer-specific requirements to its suppliers.'],
['8.4.3.2','Supplier Quality Agreements','IATF','Operation','8','The organization shall have quality agreements with all significant suppliers defining specific quality requirements, measurement systems, records retention, and right-to-audit.','1. Do you have quality agreements with all direct material suppliers — show an example.\n2. What does the quality agreement include — inspection requirements, records, audit rights, SPC?\n3. How are quality agreements kept current when requirements change?\n4. What is the consequence when a supplier violates the quality agreement?\n5. Have you exercised the right-to-audit clause recently — show the audit record.','Supplier Quality Agreements, Agreement Register, Right-to-Audit Exercise Records','Supplier Quality / Legal','The organization shall have quality agreements with its suppliers defining specific quality requirements and the right to audit.'],
['8.5.1.4','Verification After Shutdown','IATF','Operation','8','When manufacturing is interrupted or restarted after shutdown, verification activities must be performed before releasing production to ensure product conformance.','1. What verification activities are performed when production restarts after a planned or unplanned shutdown?\n2. Show me the startup verification checklist — what is checked before releasing parts?\n3. Who has authority to approve production restart after a quality-related shutdown?\n4. For unplanned shutdowns (power failure, machine breakdown), what additional checks are required?\n5. Have you ever resumed production without completing startup verification — what controls prevent this?','Startup Verification Checklist, Production Resume Authorization, Shutdown/Restart Log','Production / Quality','The organization shall define and implement a process for verifying product conformance after unplanned production shutdowns or other interruptions.'],
['8.5.1.6','Job Set-Up Verification','IATF','Operation','8','The organization must have a process for job setup verification and first-off part approval — with instructions available to the operator. Reference parts and counter samples must be retained where required.','1. Show me the job setup verification procedure — what checks are done before starting a new job?\n2. Is first-off part approval documented — who approves and what is the approval criterion?\n3. Are reference parts (golden samples, last-off) used and retained — show me an example.\n4. How are setup parameters (speed, feed, temperature, pressure) verified against the control plan?\n5. What happens if a setup fails verification — can production start before approval is given?','Job Setup Verification Sheet, First-Off Approval Records, Reference Part Log, Setup Parameters vs. Control Plan','Production / Quality','The organization shall have a documented process for job setup verification including first-off part approval — with setup verification instructions available to the operator.'],
['8.5.1.7','Process Monitoring','IATF','Operation','8','Statistical or other methods shall be used to monitor processes and process parameters — including SPC charts for key characteristics where required by customers or the control plan.','1. Show me the SPC charts used in production — which characteristics are monitored?\n2. Are SPC charts being actively used for process control, or just for data collection?\n3. Who monitors SPC charts in real time — what is the response when a chart shows out-of-control conditions?\n4. Are control limits on SPC charts based on process data or are they arbitrary?\n5. Show me a case where SPC identified a trend before product went out of spec — what action was taken?','SPC Control Charts, Process Monitoring Records, Out-of-Control Reaction Plan, SPC Training Records','Production / Quality','Statistical methods shall be used to monitor process parameters — including SPC for characteristics identified in the control plan.'],
['8.5.2.1','Identification and Traceability — Supplemental','IATF','Operation','8','The organization must have a documented process to ensure traceability by maintaining identification of product from receipt of materials through delivery, including the identification of the control plan reference point.','1. Can you trace a finished part back to the raw material batch it came from — demonstrate with a specific part.\n2. How is traceability maintained through external processing (heat treatment, plating)?\n3. What unique identification system is used — serial number, batch/lot, date code?\n4. How long are traceability records retained — is this per customer or regulatory requirement?\n5. In a recall situation, how quickly can you identify and contain all potentially affected product?','Traceability Procedure, Batch/Lot Records, Production Log, Material Traceability Matrix','Production / Quality / Logistics','The organization shall maintain identification of product from receipt through delivery — ensuring traceability to the control plan and applicable reference points.'],
['8.5.4.1','Preservation — Supplemental','IATF','Operation','8','The organization must include a risk analysis with regard to the requirement for the use of alternate preservation methods.','1. How do you assess risks to product preservation — humidity, temperature, vibration, contamination?\n2. What alternate preservation methods are available if normal packaging fails?\n3. Are preservation requirements defined in the control plan and communicated to logistics?\n4. How is preservation verified during storage and transit — what checks are performed?\n5. Show me a case where a preservation issue caused a quality problem — how was it resolved?','Preservation Procedure, Packaging Specifications, Preservation Risk Analysis, Storage Condition Records','Quality / Logistics / Production','The organization shall maintain a risk analysis regarding the use of alternate preservation methods for products and materials.'],
['8.5.5.1','After-Sales Service Information Feedback','IATF','Operation','8','The organization must have a process for communication of field failure and warranty data to manufacturing, engineering, and design functions.','1. How is warranty failure data communicated to the engineering and manufacturing teams?\n2. Show me a recent example where warranty data triggered a process or design improvement.\n3. Is there a regular warranty review meeting — who attends and what decisions are made?\n4. How quickly does warranty failure information reach the production team?\n5. How are warranty improvement actions tracked and their effectiveness verified?','Warranty Analysis Reports, Warranty Review Meeting Minutes, Engineering Change Records Triggered by Warranty','Customer Quality / Engineering / Manufacturing','The organization shall have a process for communicating field failure and warranty information to manufacturing, engineering, and design functions.'],
['8.5.5.2','Service Agreement with Customer','IATF','Operation','8','Where there are service agreements with customers, the organization shall verify that service centers have the proper tools, equipment, spare parts, technical training, and documented information.','1. Do you have service agreements with customers — what is included in the service scope?\n2. How do you verify that service centers have the required tools and qualified technicians?\n3. Are service technicians trained and certified to perform the required service activities?\n4. How is spare parts availability monitored to meet service agreement requirements?\n5. How are service quality failures (poor repair, repeat failures) investigated?','Service Agreements, Service Center Verification Records, Technician Certification Records, Spare Parts Availability Reports','After-Sales / Quality','Where service agreements exist, the organization shall verify that service centers have appropriate tools, technical training, and documented information.'],
['8.5.6.1','Control of Changes — Supplemental','IATF','Operation','8','Production process changes must include review of potential effects on fit, form, function, performance, and product safety. Changes shall be approved by the customer where required.','1. Show me the production process change request form — what risk dimensions are evaluated?\n2. Who approves production process changes internally — and when must the customer approve?\n3. How do you track which customer requires notification for which type of change?\n4. Has a process change ever caused a product escape — how was this managed?\n5. How long does the customer approval process typically take — what controls exist during waiting period?','Process Change Request Form, Change Impact Assessment, Customer Approval Records, Process Change Log','Engineering / Quality','Production process changes shall be reviewed for potential effects on fit, form, function, performance, and safety — with customer approval obtained where required.'],
['8.5.6.1.1','Temporary Changes to Process Controls','IATF','Operation','8','The organization must have a documented process for the use of alternative control methods including process controls, alternative process monitoring, and 100% inspection as temporary controls.','1. Show me the process for implementing a temporary deviation or change to process controls.\n2. Who authorizes temporary changes to process controls — is customer involvement required?\n3. How are temporary changes identified on the shop floor (visual management, labeling)?\n4. What is the maximum duration for a temporary change — how is it tracked for reversal?\n5. When a temporary change exceeds its authorized duration, what is the escalation process?','Temporary Deviation Procedure, Deviation Authorization Records, Deviation Tracking Log, Reversion Records','Quality / Production','The organization shall have a documented process for using alternative control methods as temporary measures — with defined authorization and tracking of reversal.'],
['8.6.1','Acceptance Criteria','IATF','Operation','8','Organization must document acceptance criteria for products — including critical, significant, and all other characteristics. For attribute data, the sample plan must be statistically valid.','1. Show me the acceptance criteria for a critical characteristic — how was the criterion established?\n2. For attribute inspection, what sampling plan is used — is it AQL-based or 100%?\n3. Are acceptance criteria customer-approved for significant and critical characteristics?\n4. How are acceptance criteria communicated to operators and inspectors at the point of inspection?\n5. When acceptance criteria are changed, how is this approved and communicated?','Inspection Criteria Documents, Sampling Plans, Customer-Approved Acceptance Criteria, Control Plan','Quality','Acceptance criteria for products shall be documented — including statistical sampling plans for attribute characteristics.'],
['8.6.2','Layout Inspection and Functional Testing','IATF','Operation','8','Layout inspection and functional verification to customer engineering material and performance standards shall be performed at a frequency defined in the control plan.','1. Show me the schedule for layout inspection — which products require it and at what frequency?\n2. Show me the last layout inspection report — what characteristics were measured and what were the results?\n3. How is layout inspection frequency determined — customer requirement or internal decision?\n4. What happens if layout inspection reveals a non-conformance — what is the escalation process?\n5. Is layout inspection conducted with calibrated measurement equipment — show the calibration records.','Layout Inspection Plan, Layout Inspection Reports, Functional Test Reports, Calibration Records','Quality','Layout inspection and functional verification shall be performed at a frequency defined in the control plan to applicable engineering standards.'],
['8.6.3','Appearance Items','IATF','Operation','8','Where products are designated as appearance items by the customer, the organization must provide appropriate resources, including lighting, master samples, and trained appraisers.','1. Do you have any appearance-critical parts — what are they?\n2. Show me the appearance master samples — are they current, identified, and controlled?\n3. What lighting conditions are used for appearance inspection — are they per customer standard?\n4. How are appearance appraisers trained and qualified — is there an inter-appraiser agreement?\n5. Show me the last appearance inspection record — what criteria were evaluated?','Appearance Inspection Standard, Master Sample Register, Appraiser Training Records, Appearance Inspection Records','Quality','For appearance items, the organization shall provide appropriate resources including lighting, reference samples, and trained appraisers.'],
['8.6.5','Statutory and Regulatory Conformity — Material Declaration','IATF','Operation','8','Products and materials shall conform to all applicable statutory and regulatory requirements — including material composition declarations and substance restrictions.','1. Show me the material composition declarations for current products — are they current?\n2. How do you track compliance with REACH SVHC, RoHS, and other substance restrictions?\n3. How are material declarations obtained and verified from suppliers?\n4. What process ensures regulatory changes are identified and implemented in a timely manner?\n5. Have you ever supplied product that did not meet regulatory substance requirements — what happened?','Material Composition Declarations, IMDS Submissions, REACH/RoHS Compliance Records, Substance Restriction Register','Quality / Engineering / Purchasing','Products and materials shall conform to all applicable statutory and regulatory requirements — including material composition and substance declarations.'],
['8.6.6','Acceptance Records','IATF','Operation','8','Acceptance records shall provide evidence that defined acceptance criteria have been met. Records must identify the person who authorized the release and equipment used.','1. Show me a final inspection acceptance record — does it identify the inspector and equipment used?\n2. How are acceptance records linked to the specific production batch or lot?\n3. How long are acceptance records retained — is this per customer or regulatory requirement?\n4. When 100% inspection is required, how is this documented to prove all parts were checked?\n5. Can you produce acceptance records for a product shipped 6 months ago — show an example?','Inspection Records, Final Release Records, Inspector Identification Records, Retention Schedule','Quality','Acceptance records shall include evidence that defined acceptance criteria have been met — with identification of the person authorizing release and measurement equipment used.'],
['8.7.1.2','Customer Notification for Non-Conforming Product','IATF','Operation','8','When non-conforming product may have been shipped to customer, the organization must notify the customer immediately and maintain records of this notification.','1. Show me the process for notifying customers when suspect or non-conforming product may have been shipped.\n2. What is the maximum acceptable time between identifying an escape and notifying the customer?\n3. Who has authority to issue a customer notification — is there an approval process?\n4. Show me a recent customer notification — what information was included?\n5. How do you track customer notifications and their resolution?','Customer Notification Records, Escape Containment Records, Notification Approval Authorization','Customer Quality / Quality','When non-conforming product may have shipped to customers, the organization shall notify the affected customer promptly and maintain records of all such notifications.'],
['8.7.1.3','Customer Waiver for Non-Conforming Product','IATF','Operation','8','Before processing non-conforming product as a customer waiver/deviation, the organization must obtain customer authorization. Records of expiration dates and part numbers must be maintained.','1. Show me a recent customer waiver/deviation request — what information was included?\n2. How do you track deviation expiry dates and quantities — what happens when limits are reached?\n3. Has production continued beyond the waiver limit — what controls prevent this?\n4. How are waivered parts identified and separated from conforming production?\n5. How is the root cause for the waiver condition addressed before it expires?','Customer Waiver/Deviation Records, Deviation Tracking Register, Identified Non-Conforming Product Records','Quality / Production','Customer authorization (waiver/deviation) shall be obtained before processing non-conforming product — with records of expiration dates and quantities.'],
['8.7.1.4','Rework Documentation','IATF','Operation','8','The organization must have a documented process for reworking non-conforming product — including instructions, re-inspection, traceability, and risk assessment before release.','1. Show me the rework instructions for a common non-conformance — are they documented and approved?\n2. How is reworked product re-inspected — what criteria must it meet?\n3. Is there a risk assessment before authorizing rework — who approves the rework plan?\n4. How are reworked parts identified and traceable throughout the rework process?\n5. If rework instructions are not available, can rework still be performed — what is the process?','Rework Instructions, Rework Authorization, Re-inspection Records, Rework Traceability Records, Rework Risk Assessment','Quality / Production','The organization shall have documented rework instructions — including re-inspection, traceability, and risk assessment — prior to reworking non-conforming product.'],
['8.7.1.5','Repair Documentation','IATF','Operation','8','The organization must have a process for repair of non-conforming product that includes customer approval, documented repair instructions, risk analysis, and re-verification.','1. Is repair authorized by the customer for any of your products — show the customer approval.\n2. Are there documented repair instructions approved for use on specific products?\n3. How is repaired product re-verified — what criteria must it meet before release?\n4. How are repair records maintained and linked to specific parts?\n5. Has a repair ever failed in the field — how was this investigated and what was learned?','Customer Repair Authorization, Repair Instructions, Repair Re-verification Records, Repair Traceability Records','Quality','The organization shall have a process for repair of non-conforming product — including customer approval, documented repair instructions, and re-verification.'],
['8.7.1.6','Notification of Suspected Nonconformance','IATF','Operation','8','When the organization suspects that non-conforming product may have been shipped to customers, it must notify the customer promptly and initiate containment actions immediately.','1. What triggers a suspected escape notification — what criteria are used?\n2. Show me the escalation process when a potential escape is identified.\n3. How quickly is the customer notified — within hours or days?\n4. Who decides whether to initiate a recall or stop shipment?\n5. Show me the containment actions taken during a recent suspected escape.','Suspected Escape Notification Records, Containment Action Records, Customer Communication Log','Customer Quality / Quality / Management','The organization shall notify the customer promptly when it suspects non-conforming product may have been shipped — and initiate containment actions.'],
['8.7.1.7','Disposition of Non-Conforming Product','IATF','Operation','8','Non-conforming product must be clearly identified, segregated, and dispositioned (scrap, rework, repair, use-as-is, return to supplier, deviation) following defined procedures.','1. Show me the non-conforming material area — is it physically segregated and clearly identified?\n2. Who has authority to disposition non-conforming material for each option (rework, scrap, deviation)?\n3. How is the disposition decision documented and traceable to the specific NCR?\n4. How do you prevent non-conforming material from being accidentally used in production?\n5. Are there specific requirements for scrapping safety-critical parts — how are they destroyed?','Non-Conforming Material Procedure, NCR Disposition Records, Scrap Destruction Records, MRB Authorization','Quality','Non-conforming product shall be identified, segregated, and dispositioned — with documented procedures for each disposition path.'],
['9.1.1.1','Monitoring of Manufacturing Processes','IATF','Performance Evaluation','9','The organization shall monitor manufacturing processes to ensure they are operating to control plan requirements — including process parameters and product characteristics.','1. Show me how monitoring of process parameters is documented — is it tied to the control plan?\n2. What is the reaction when a monitored parameter goes outside the control limits?\n3. Who is responsible for reviewing process monitoring data — how often?\n4. How are process monitoring records retained and made available for customer audits?\n5. Show me evidence from the last 3 months that process monitoring was consistently performed.','Process Monitoring Records, Control Plan, Out-of-Control Reaction Plans, Process Parameter Logs','Production / Quality','The organization shall monitor manufacturing processes to ensure they conform to control plan requirements.'],
['9.1.1.2','Manufacturing Process Monitoring','IATF','Performance Evaluation','9','Statistical process control (SPC) shall be used to monitor process output — with statistical capability (Cpk) assessed for process stability and capability.','1. Show me the Cpk results for all special characteristic features — what is the minimum Cpk achieved?\n2. How is process capability tracked over time — is there a trend analysis?\n3. When Cpk drops below 1.67 for a special characteristic, what is the reaction?\n4. How is the SPC data collected — automated or manual — and how is integrity verified?\n5. Are control charts updated in real time or after the fact — who reviews them daily?','Cpk Study Reports, SPC Control Charts, Process Capability Tracking Log, Out-of-Capability Reaction Plans','Production / Quality','Statistical process control shall be used to monitor manufacturing process output — with Cpk results documented and tracked.'],
['9.1.1.3','Identification of Statistical Tools','IATF','Performance Evaluation','9','Appropriate statistical tools shall be identified during advanced quality planning and included in the control plan.','1. Show me how statistical tools were selected for each process step in APQP.\n2. Are the statistical tools in the control plan appropriate for the type of data (variable vs attribute)?\n3. Who decides which statistical tools to use — is there a statistician or quality engineer involved?\n4. Are all employees who use statistical tools trained on their correct application?\n5. How do you verify that the correct statistical tool is being used for each characteristic?','Control Plan with Statistical Tool Identification, APQP Records, Statistical Tool Training Records','Quality / Engineering','Appropriate statistical tools shall be identified during advanced quality planning and included in the control plan.'],
['9.1.2.1','Customer Satisfaction — Supplemental','IATF','Performance Evaluation','9','Customer satisfaction must be monitored through performance indicators including quality performance (PPM), delivery, and customer scorecards. Must include a mechanism for two-way communication with customer.','1. Show me the customer satisfaction monitoring process — what KPIs are tracked per customer?\n2. How are customer scorecards reviewed and responded to?\n3. Are there customer satisfaction targets — what are they and are they being met?\n4. When a customer rates performance as poor, what is the formal response process?\n5. How is customer satisfaction data presented at management review?','Customer Scorecard Register, PPM by Customer, OTD by Customer, Customer Satisfaction Dashboard, Management Review Inputs','Customer Quality / Quality / Sales','Customer satisfaction shall be monitored through KPIs including PPM quality performance, delivery, and customer scorecards — with a two-way communication mechanism.'],
['9.1.3.1','Prioritization','IATF','Performance Evaluation','9','The organization must prioritize the use of customer-related data, such as warranty data, for quality improvement — focusing on systemic quality failures.','1. How do you prioritize quality improvements — what methodology is used (Pareto, risk-based)?\n2. Show me the top 5 quality issues identified from customer data in the last 12 months — what actions are being taken?\n3. How is warranty data analyzed to identify systemic failures vs. one-off incidents?\n4. Are improvement priorities aligned with customer expectations — how do you know?\n5. How are resources allocated to priority improvement projects vs. routine quality activities?','Quality Improvement Priority List, Warranty Pareto Analysis, Customer Data Analysis Reports','Quality Management','The organization shall prioritize quality improvements based on customer-related data including warranty analysis — focusing on systemic failures.'],
['9.2.2.1','Internal Audit Programme — Supplemental','IATF','Performance Evaluation','9','The internal audit programme shall include system audits, manufacturing process audits, and product audits — with each type scheduled to verify compliance and effectiveness.','1. Show me the annual audit plan — does it distinguish between system, process, and product audits?\n2. How are system audits, process audits, and product audits scheduled — what is the frequency of each?\n3. Who performs each type of audit — are there dedicated product and process auditors?\n4. How are audit findings tracked to closure — show the open findings register.\n5. When critical audit findings remain open past their due date, what is the escalation process?','Annual Audit Plan with 3 Audit Types, Audit Schedule, Open Findings Register, Auditor Qualification Matrix','Internal Audit / Quality','The audit programme shall cover system audits, manufacturing process audits, and product audits — with findings tracked to closure.'],
['9.2.2.2','Internal Audit of QMS — Supplemental','IATF','Performance Evaluation','9','All QMS requirements shall be audited in a cycle — considering importance of processes, customer complaints, internal quality issues, and results of previous audits.','1. Show me how the audit cycle is planned — are all clauses covered in the annual cycle?\n2. How are high-risk or previously non-compliant areas given higher audit frequency?\n3. When a customer complaint occurs, does it trigger an unplanned audit of the related process?\n4. Are audit conclusions used to adjust future audit scope and frequency?\n5. Show me the last complete audit cycle — which clauses were audited and what were the findings?','Audit Cycle Plan, Audit Reports by Clause, Audit Cycle Completion Record','Internal Audit / Quality','All QMS requirements shall be audited within a defined cycle — with frequency adjusted based on risk, complaints, and previous findings.'],
['9.3.2.1','Management Review — Action Plans','IATF','Performance Evaluation','9','When customer performance targets are not being met, a documented action plan shall be created — with evidence of improvement toward targets.','1. Are there any customers where performance targets are not being met — show the action plan.\n2. Who owns the action plan for each underperforming customer KPI?\n3. How is progress toward the action plan reviewed — at what frequency?\n4. When an action plan is ineffective, how is this escalated?\n5. Show me an action plan from a previous management review — was the target eventually met?','Customer Performance Action Plans, Management Review Action Tracking, Target Achievement Records','Quality / Top Management / Customer Quality','When customer performance targets are not met, documented action plans shall be developed and tracked to completion.'],
['10.2.3','Problem Solving','IATF','Improvement','10','The organization shall have a documented process for problem solving — appropriate to the problem type. Must use appropriate methodology (8D, DMAIC, etc.) and include lessons learned. Must prevent recurrence across similar products and processes.','1. Show me the problem-solving process — what methodologies are available for different problem types?\n2. When is 8D used vs. 5-Why vs. DMAIC — how is the right method selected?\n3. How do you ensure horizontal deployment of solutions to similar products or processes?\n4. Show me a lessons learned that was derived from a major customer complaint — how was it shared?\n5. How is the effectiveness of problem solving verified after implementation?','Problem Solving Procedure, 8D Reports, DMAIC Projects, Lessons Learned Database, Horizontal Deployment Records','Quality','The organization shall have a documented process for problem solving — with appropriate methodology selection, lessons learned capture, and horizontal deployment of solutions.'],
['10.2.4','Error-Proofing','IATF','Improvement','10','The organization shall have a documented process for determining the use of error-proofing methodology. Details of the method used shall be documented in the process FMEA and verified during audits.','1. Show me how error-proofing devices are identified and implemented for special characteristics or high-risk operations.\n2. Are all poka-yoke devices listed in the PFMEA and control plan?\n3. How are error-proofing devices tested and verified — what is the test frequency?\n4. What happens if an error-proofing device fails — what is the reaction plan?\n5. How are error-proofing devices maintained and their effectiveness validated periodically?','Error-Proofing Register, PFMEA with Poka-Yoke entries, Control Plan with Error-Proofing, Poka-Yoke Verification Records','Engineering / Quality / Production','The organization shall have a documented process for determining the use of error-proofing methodology — with details documented in PFMEA and verified during audits.'],
['10.2.5','Warranty Management Systems','IATF','Improvement','10','If the organization has warranty work as a business requirement, the organization must have a process to analyze warranty returns. A no-trouble-found (NTF) process must be included.','1. Show me the warranty management process — from receipt of warranty return to root cause analysis.\n2. How do you categorize warranty returns — by defect type, part, customer, region?\n3. What is your No-Trouble-Found (NTF) rate — and what actions are taken for NTF returns?\n4. How are warranty failures analyzed as a leading indicator for quality improvement?\n5. How are warranty claims linked back to specific production batches for root cause analysis?','Warranty Return Analysis Reports, NTF Process Records, Warranty Pareto, Root Cause Analysis for Warranty','Customer Quality / Engineering','If warranty is a business requirement, the organization shall have a warranty management system including analysis of warranty returns and a No-Trouble-Found process.'],
['10.2.6','Customer Complaints and Field Information Analysis','IATF','Improvement','10','The organization shall have a documented process for problem solving — appropriate to the problem type. Must use appropriate methodology and must include lessons learned. Must prevent recurrence across similar products and processes.','1. How do you analyze customer complaint data for systemic trends — not just individual complaints?\n2. Is there a regular complaint review meeting — who attends and what decisions are made?\n3. How are lessons learned from customer complaints shared across the organization?\n4. Show me a case where complaint analysis identified a systemic issue — what was changed?\n5. How are field failure analysis results integrated back into PFMEA and control plan updates?','Complaint Analysis Reports, Trend Analysis, Lessons Learned Database, PFMEA Updates Triggered by Complaints','Customer Quality / Quality','The organization shall analyze customer complaint and field information data — using appropriate problem solving methods with lessons learned and horizontal deployment.'],
['10.3.1','Continual Improvement — Supplemental','IATF','Improvement','10','The organization shall have a documented process for continual improvement — including manufacturing process improvement focusing on reducing variation and waste. Must include a business plan for improvement.','1. Show me the continual improvement plan — is it documented and approved by management?\n2. How are Lean and waste reduction activities structured — is there a formal program?\n3. What measurable improvements in PPM, OEE, scrap, or cycle time were achieved last year?\n4. How does the CI plan link to business objectives and customer expectations?\n5. How are improvement ideas from operators captured and implemented — show the process.','Continual Improvement Plan, CI Project Register, Lean/Kaizen Records, Improvement Metric Trends','Quality / Production / Management','The organization shall have a documented process for continual improvement — including manufacturing process improvement with a focus on reducing variation and waste.'],
];

export function seedAuditClauses(db: InstanceType<typeof DatabaseSync>): void {
  const stmt = db.prepare(
    `INSERT OR IGNORE INTO audit_clauses
     (clause_no, clause_title, standard, section, section_no, simple_meaning, audit_questions, documents_required, applicable_process, original_requirement)
     VALUES (?,?,?,?,?,?,?,?,?,?)`
  );
  let inserted = 0;
  for (const row of NEW_CLAUSES) {
    try {
      stmt.run(...row);
      inserted++;
    } catch {
      // UNIQUE constraint — already exists, skip
    }
  }
  if (inserted > 0) {
    console.log(`[QMOS] Seeded ${inserted} new audit clauses.`);
  }
}
